def prime_fib(n: int):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def generate_fibonacci():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    fib_generator = generate_fibonacci()
    prime_fibs = []
    for _ in range(n):
        fib = next(fib_generator)
        if is_prime(fib):
            prime_fibs.append(fib)

    return prime_fibs[-1]
